      'Le modèle simple, [[פָּעַל]], donne [[לָמַד]] (il a appris). Le modèle [[פִּעֵל]], reconnaissable à sa voyelle « i » puis « é », donne souvent un sens actif : [[לִמֵּד]] (il a enseigné).',
      'Le modèle [[הִפְעִיל]], qui commence par ה au passé, veut souvent dire « faire faire » : [[רָאָה]] (il a vu) devient [[הֶרְאָה]] (il a montré, il a fait voir).',
