      'Des noms masculins prennent [[וֹת]] : [[מָקוֹם]] (lieu) devient [[מְקוֹמוֹת]]. Des noms féminins prennent [[ִים]] : [[שָׁנָה]] (année) devient [[שָׁנִים]].',
