      '[[אִם]] veut dire « si ». Pour une condition dans l’avenir, les deux verbes sont au futur : [[אִם יֵרֵד גֶּשֶׁם, נִשָּׁאֵר בַּבַּיִת]].',
      '« Quand » dans une phrase (et non dans une question) se dit [[כְּשֶׁ]], collé au mot suivant : [[כְּשֶׁהָיִיתִי יֶלֶד]], quand j’étais enfant.',
