      'Au présent, il commence par [[מַ]] : [[מַתְחִיל]] (commence), [[מַזְמִין]] (commande, invite), [[מַרְגִּישׁ]] (se sent), [[מַסְבִּיר]] (explique).',
      'Au passé, il commence par [[הִ]] : [[הִזְמַנְתִּי]], j’ai réservé. Au futur, par [[אַ]] pour « je » : [[אַזְמִין]], je commanderai.',
