      '« Sans + verbe » : [[בְּלִי]] + infinitif : [[בְּלִי לְהַגִּיד שָׁלוֹם]], sans dire au revoir. « Sans que » : [[בְּלִי שֶׁ]] + phrase : [[הוּא יָצָא בְּלִי שֶׁרָאִיתִי]], il est sorti sans que je le voie.',
